import math
from itertools import product

# Define the set of allowed values
vals = [-2, -1, 0, 1, 2]

def is_prime(n):
    """Checks if n is a prime number (positive integer > 1)."""
    if n <= 1:
        return False
    if n <= 3:
        return True
    if n % 2 == 0 or n % 3 == 0:
        return False
    i = 5
    while i * i <= n:
        if n % i == 0 or n % (i + 2) == 0:
            return False
        i += 6
    return True

def evaluate_N(x, y, z):
    """
    Evaluates N = y^x * z^y * x^z.
    Handles 0^0 case by assuming 1.
    Returns None if the expression is undefined (e.g., 0^negative).
    """
    def power(base, exp):
        if base == 0:
            if exp == 0:
                return 1  # Assumption: 0^0 = 1
            elif exp > 0:
                return 0
            else: # exp < 0
                return None # Undefined

        # Standard integer power calculation
        try:
            return base ** exp
        except OverflowError:
            # Should not happen with these small inputs, but good practice
            return None

    term1 = power(y, x)
    term2 = power(z, y)
    term3 = power(x, z)

    if term1 is None or term2 is None or term3 is None:
        return None

    N = term1 * term2 * term3
    return N

good_triples = []

